    buf = [None] * capacity
    head = size = 0
    out = []
    for op in ops:
        if op[0] == 'enqueue':
            if size == capacity:
                out.append(False)
            else:
                buf[(head + size) % capacity] = op[1]
                size += 1
                out.append(True)
        elif op[0] == 'dequeue':
            if size == 0:
                out.append(-1)
            else:
                out.append(buf[head])
                head = (head + 1) % capacity
                size -= 1
        else:
            out.append(size == capacity)
    return out
